#!/usr/bin/env python3
"""Replay fixed-workload before/after download paging, stale request and read-gate costs."""
import argparse,hashlib,json,os,pathlib,subprocess,tempfile
ROOT=pathlib.Path(__file__).resolve().parents[2];HERE=pathlib.Path(__file__).resolve().parent;PROD=ROOT/'app/src/main/java/local/pocketchat';RECOVERY=ROOT/'tests/download-recovery-host/android/os'
BASELINE={'DownloadDisplayCache.java':'8bb2d4bf5a3aa40190c2c1f31f07dc30a9666acd0f570670c0324a6051a4070e','DownloadPageWindow.java':'023aafd93a6070fba6bf4ceb6bd06cbdb664d346fd7c0e86cd169c962984aa98','DownloadQuery.java':'1da37fb6ae8cd2b37c3591b42ba80e822eb9c6921ddee3550a2a24e0dbbc8263'}
def main():
 p=argparse.ArgumentParser();p.add_argument('--java-home',type=pathlib.Path,required=True);p.add_argument('--json-jar',type=pathlib.Path,required=True);p.add_argument('--before',action='store_true');p.add_argument('--output',type=pathlib.Path,required=True);a=p.parse_args();a.output.mkdir(parents=True,exist_ok=True)
 sources={n:HERE/'baseline'/ (n+'.in') if a.before else PROD/n for n in BASELINE};
 for name,path in sources.items():
  if a.before:assert hashlib.sha256(path.read_bytes()).hexdigest()==BASELINE[name],'Historical snapshot changed: '+name
 sources.update({n:PROD/n for n in ['J.java','DownloadListPolicy.java','DownloadOwnerLabels.java','DownloadReadGate.java']})
 fixture=(HERE/'WorkerCases.java.in').read_text()
 callback='page->{succeeded.incrementAndGet();callbacks.countDown();},error->{if(error instanceof CancellationException)cancelled.incrementAndGet();callbacks.countDown();}'
 if a.before:
  fixture=fixture.replace('/* SCOPE_DECLARATION */','').replace('/* QUEUED_REQUEST */','DownloadDisplayCache.request(new Context(),0,"","",query,'+callback+');').replace('/* INDEPENDENT_SCOPES */','')
  old=(HERE/'baseline/DesignDownloads.java.in').read_text();prefix='if(loading){pending=true;return;}loading=true;pending=false;';assert old.count(prefix)==1
  fixture=fixture.replace('/* READ_GATE */','HistoricalReadGate gate=new HistoricalReadGate();gate.refresh();for(int i=0;i<100;i++)gate.refresh();gate.loading=false;if(gate.pending){gate.pending=false;gate.refresh();}measurements.put(J.obj("workload","100 duplicate refresh events during one unchanged read","startedReads",gate.starts));check("Captured refresh prefix replays duplicate unchanged events",gate.starts==2);')
  fixture+='\nclass HistoricalReadGate{boolean loading,pending;int starts;void refresh(){'+prefix+'starts++;}}\n'
 else:
  fixture=fixture.replace('/* SCOPE_DECLARATION */','DownloadDisplayCache.Scope scope=new DownloadDisplayCache.Scope();').replace('/* QUEUED_REQUEST */','scope.invalidate();DownloadDisplayCache.request(new Context(),0,"","",query,scope,'+callback+');')
  fixture=fixture.replace('/* INDEPENDENT_SCOPES */','''CountDownLatch held=new CountDownLatch(1),release=new CountDownLatch(1),done=new CountDownLatch(2);AtomicInteger good=new AtomicInteger(),bad=new AtomicInteger();DownloadDisplayCache.Scope first=new DownloadDisplayCache.Scope(),second=new DownloadDisplayCache.Scope();DownloadDisplayCache.worker.execute(()->{held.countDown();try{release.await();}catch(InterruptedException error){throw new RuntimeException(error);}});check("Independent scope worker held",held.await(5,TimeUnit.SECONDS));DownloadDisplayCache.request(new Context(),0,"","",DownloadQuery.all(),first,p->{good.incrementAndGet();done.countDown();},e->{bad.incrementAndGet();done.countDown();});DownloadDisplayCache.request(new Context(),0,"","",DownloadQuery.all(),second,p->{good.incrementAndGet();done.countDown();},e->{bad.incrementAndGet();done.countDown();});first.invalidate();release.countDown();check("Invalidating one host leaves the other host live",done.await(10,TimeUnit.SECONDS)&&good.get()==1&&bad.get()==1);''')
  fixture=fixture.replace('/* READ_GATE */','''DownloadReadGate gate=new DownloadReadGate();int started=gate.begin(1,7)?1:0;for(int i=0;i<100;i++)if(gate.begin(1,7))started++;gate.complete();if(gate.replay(1)&&gate.begin(1,7))started++;measurements.put(J.obj("workload","100 duplicate refresh events during one unchanged read","startedReads",started));check("Duplicate unchanged progress events never schedule a second read",started==1);check("Changed data can start the next read",gate.begin(1,8));for(int i=0;i<100;i++)check("Dirty burst remains coalesced",!gate.begin(2,9));gate.complete();check("Newer query/data requests replay exactly once",gate.replay(2));check("Replay starts after cancellation callback released loading",gate.begin(2,9));gate.complete();check("Completed replay does not loop",!gate.replay(2));''')
 inputs=[*sources.values(),HERE/'WorkerCases.java.in',HERE/'baseline/DesignDownloads.java.in',pathlib.Path(__file__).resolve(),RECOVERY/'Handler.java',RECOVERY/'Looper.java'];hashes={str(f.relative_to(ROOT)):hashlib.sha256(f.read_bytes()).hexdigest()for f in inputs}
 with tempfile.TemporaryDirectory(prefix='download-worker-perf-')as raw:
  temp=pathlib.Path(raw);pkg=temp/'local/pocketchat';pkg.mkdir(parents=True);(pkg/'DownloadWorkerPerformanceCases.java').write_text(fixture)
  for name,path in sources.items():(pkg/name).write_bytes(path.read_bytes())
  (temp/'android/content').mkdir(parents=True);(temp/'android/content/Context.java').write_text('package android.content;public class Context{}')
  (temp/'android/os').mkdir(parents=True)
  for name in ['Handler.java','Looper.java']:(temp/'android/os'/name).write_bytes((RECOVERY/name).read_bytes())
  (temp/'android/os/Bundle.java').write_text('package android.os;public class Bundle{java.util.Map<String,Object> values=new java.util.HashMap<>();public void putLong(String k,long v){values.put(k,v);}public long getLong(String k){return ((Number)values.getOrDefault(k,0L)).longValue();}}')
  classes=temp/'classes';compile=subprocess.run([str(a.java_home/'bin/javac'),'-encoding','UTF-8','-cp',str(a.json_jar),'-d',str(classes),*map(str,temp.rglob('*.java'))],text=True,capture_output=True);(a.output/'compile.stdout.txt').write_text(compile.stdout);(a.output/'compile.stderr.txt').write_text(compile.stderr);compile.check_returncode()
  run=subprocess.run([str(a.java_home/'bin/java'),'-Dbefore='+str(a.before).lower(),'-cp',str(classes)+os.pathsep+str(a.json_jar),'local.pocketchat.DownloadWorkerPerformanceCases'],text=True,capture_output=True,timeout=120);(a.output/'stdout.txt').write_text(run.stdout);(a.output/'stderr.txt').write_text(run.stderr);run.check_returncode();report=json.loads(run.stdout);report.update(sourceFiles=hashes,fixtureSha256=hashlib.sha256(fixture.encode()).hexdigest(),executionInputsUnchanged=all(hashlib.sha256((ROOT/n).read_bytes()).hexdigest()==h for n,h in hashes.items()));(a.output/'results.json').write_text(json.dumps(report,ensure_ascii=False,indent=2)+'\n');assert report['executionInputsUnchanged'];print(json.dumps({'status':report['status'],'variant':report['variant'],'checks':report['total'],'measurements':report['measurements'],'output':str(a.output)}))
if __name__=='__main__':main()
